// js/registry.js — the STATIONS manifest. Pure data: no DOM, no imports, no side effects.
// Importable from Node (tools/smoke.mjs reads the routes from here).
//
// Each entry is one place on the Story Map. `id` is also the hash route (#roots).
// `module` is relative to js/ (the router lives in js/app.js and does `import(module)`).
// `problems` are review-problem ids from docs/ASSIGNMENT.md section 2; `topics` are the
// syllabus ids from section 3. `threads` are the story thread lines (docs/STORY.md section 2)
// that pass through the station: T1 addresses, T2 staircase, T3 motion-and-zoom.
// `order` is the Story Map order (home first, problems last); `part` groups the map.
// `map` is which course section lists the place: 'test1' (the default), 'test2', or 'shared'
// (home, which sits on both maps). A missing `map` means Test 1, so older entries stay put.
//
// Maintained by the Goal Planner. Stations do not edit this file.

export const THREADS = [
  { id: 'T1', title: 'One point, two addresses', tone: '--cart', dash: false, maps: ['test1'],
    summary: 'Cartesian says where z sits (a slide); polar says how to reach it (turn, then stretch). Pick the native address.' },
  { id: 'T2', title: 'The staircase: z, arg z, Arg z', tone: '--polar', dash: true, maps: ['test1'],
    summary: 'A move has infinitely many names; arg z is all of them, Arg z is the home step, z is the point on the floor.' },
  { id: 'T3', title: 'A function is a motion; a derivative is a move seen up close', tone: '--output', dash: false, maps: ['test1'],
    summary: 'Strokes are carried on one clock; under a microscope a differentiable map is a single spin-and-stretch (no mirror).' },
  { id: 'C1', title: 'From the plane to the circuit', tone: '--input', dash: false, maps: ['test1'],
    summary: 'A turn on the plane is a current in a circuit. The thread stops for the polar address, the multiply, the argument, and the powers, then skips ahead to the circuit.' },
];

// A hash token such as t2 or f2. Case does not matter. Unknown tokens are null,
// so a typo does not force a map.
export function threadByToken(token) {
  const key = String(token || '').toLowerCase();
  if (!key) return null;
  return THREADS.find((t) => String(t.id).toLowerCase() === key)
    || FRACTAL_THREADS.find((t) => String(t.id).toLowerCase() === key)
    || null;
}

// The one way a thread is named on a badge, a map legend or a link: "T2 \u00b7 The staircase" (the id, then the title up to its first colon or semicolon).
// Takes a thread entry or a thread id; an unknown id comes back as it is.
export function threadLabel(thread) {
  const th = typeof thread === 'string'
    ? (THREADS.find((t) => t.id === thread) || FRACTAL_THREADS.find((t) => t.id === thread))
    : thread;
  if (!th || !th.id) return String(thread);
  return `${th.id} \u00b7 ${String(th.title).split(/[:;]/)[0].trim()}`;
}

// The words in front of a link that follows a thread rather than the Story Map order: "T2 next: ", "T1 previous: ". Every station writes its thread links this way.
export function threadLinkPrefix(threadId, dir) {
  return `${threadId} ${dir === 'prev' ? 'previous' : 'next'}: `;
}

// Test 2 threads. They are not T1–T3, so they never light up on the Test 1 map.
// F1 is the spine (a sequence has a fate). F2 is the Julia rule. F3 is Newton's step.
export const FRACTAL_THREADS = [
  { id: 'F1', title: 'A sequence has a fate', tone: '--output', dash: false, maps: ['test2'],
    summary: 'Test 1 taught one motion. Do it again and you have a sequence. The colour of a start is the fate of that sequence.' },
  { id: 'F2', title: 'Square, then slide', tone: '--cart', dash: true, maps: ['test2'],
    summary: 'The Julia rule is a power from Test 1, then a slide by c. The solid region is every start whose walk stays. The orbit of 0 decides whether the edge is one piece. The Mandelbrot set is that orbit, collected over c.' },
  { id: 'F3', title: 'Which root the walk finds', tone: '--input', dash: false, maps: ['test2'],
    summary: 'Newton’s step is one motion, z minus p(z) over p′(z). Repeat it. The colour is which root the walk reaches.' },
];

// The two course sections. Home is the switcher; each map lists its own places.
export const MAPS = Object.freeze([
  Object.freeze({ id: 'test1', title: 'Test 1', note: 'Complex numbers, Chapters 1 to 3, and the §5.4 circuit' }),
  Object.freeze({ id: 'test2', title: 'Test 2', note: 'Chapter 4: sequences, Julia, Newton' }),
]);

// localStorage key (without the mv: prefix the store adds). Both the nav and the home switcher use it.
export const MAP_STORAGE_KEY = 'map';

export function normalizeMapId(id) {
  return id === 'test2' ? 'test2' : 'test1';
}

// 'test1' | 'test2' | 'shared'. A place with no map field is Test 1.
export function mapOf(station) {
  if (!station || station.map == null || station.map === 'test1') return 'test1';
  if (station.map === 'shared') return 'shared';
  if (station.map === 'test2') return 'test2';
  return 'test1';
}

export function stationPart(station, mapId) {
  if (!station) return '';
  if (station.partByMap && Object.prototype.hasOwnProperty.call(station.partByMap, mapId)) return station.partByMap[mapId];
  return station.part;
}

export function threadsOn(station, mapId) {
  if (!station) return [];
  if (station.threadsByMap && Object.prototype.hasOwnProperty.call(station.threadsByMap, mapId)) return station.threadsByMap[mapId];
  return station.threads || [];
}

// Places on one map, in manifest order. Home is shared, so it is on both.
export function stationsForMap(mapId, stations = STATIONS) {
  const id = normalizeMapId(mapId);
  return stations.filter((s) => {
    const m = s.map || 'test1';
    return m === 'shared' || m === id;
  });
}

export function threadsForMap(mapId) {
  return mapId === 'test2' ? FRACTAL_THREADS : THREADS;
}

